-- Observational group assessments, independently scoped from fixture execution.
-- The private assessor reads issued evidence; it cannot ingest, sign or execute.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='finops_group_assessor') THEN CREATE ROLE finops_group_assessor NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;END IF;END $$;

CREATE TABLE fleet_native_assessment_requests (
 tenant_id text NOT NULL,id text NOT NULL,workload_id text NOT NULL,creator_id text NOT NULL,
 old_proposal_id text NOT NULL,candidate_proposal_id text NOT NULL,safety_profile_id text NOT NULL,safety_profile_version bigint NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,old_proposal_id) REFERENCES fleet_configuration_proposals(tenant_id,id),
 FOREIGN KEY(tenant_id,candidate_proposal_id) REFERENCES fleet_configuration_proposals(tenant_id,id),
 FOREIGN KEY(tenant_id,safety_profile_id) REFERENCES workload_safety_profiles(tenant_id,id),
 CHECK(old_proposal_id<>candidate_proposal_id),CHECK(octet_length(raw_document)<=32768)
);
CREATE TABLE fleet_native_assessments (
 tenant_id text NOT NULL,id text NOT NULL,request_id text NOT NULL,content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),
 input_snapshot_hash text NOT NULL CHECK(input_snapshot_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,request_id),FOREIGN KEY(tenant_id,request_id) REFERENCES fleet_native_assessment_requests(tenant_id,id),
 CHECK(octet_length(raw_document)<=1048576)
);
CREATE INDEX fleet_native_assessment_page ON fleet_native_assessment_requests(tenant_id,workload_id,id);
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['fleet_native_assessment_requests','fleet_native_assessments'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK(tenant_id=current_setting(''app.tenant_id'',true))',tab);
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION public.deny_evidence_mutation()',tab||'_immutable',tab);
 END LOOP;END $$;
GRANT SELECT ON fleet_native_assessment_requests,fleet_native_assessments TO finops_api,finops_group_assessor;
GRANT INSERT ON fleet_native_assessment_requests TO finops_api;
GRANT INSERT ON fleet_native_assessments TO finops_group_assessor;
-- All reads retain tenant RLS. No UPDATE/ingestion, raw-artifact publication,
-- execution, private-key or journal/controller grant belongs to this role.
GRANT SELECT ON entities,workload_safety_profiles,source_registrations,source_checkpoints,source_receipts,source_revisions,native_capacity_results,telemetry_connections,telemetry_source_revisions,telemetry_source_revocations TO finops_group_assessor;

-- Reuse the real025/027 current group resolver with its existing lock order.
-- This wrapper adds no fixture profile, model realm or instance projection.
CREATE FUNCTION fleet_native_selection_current(p_tenant text,p_old text,p_candidate text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF p_tenant IS NULL OR p_tenant='' OR p_tenant IS DISTINCT FROM current_setting('app.tenant_id',true) THEN RAISE EXCEPTION 'group assessment tenant differs';END IF;
 RETURN public.fleet_fixture_selection_current(p_tenant,p_old,p_candidate);
END $$;
REVOKE ALL ON FUNCTION fleet_native_selection_current(text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fleet_native_selection_current(text,text,text) TO finops_api,finops_group_assessor;

CREATE FUNCTION guard_fleet_native_assessment_request() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE binding jsonb;profile public.workload_safety_profiles%ROWTYPE;o public.fleet_configuration_proposals%ROWTYPE;c public.fleet_configuration_proposals%ROWTYPE;BEGIN
 IF current_user<>'finops_api' THEN RAISE EXCEPTION 'group assessment selection requires API';END IF;
 NEW.writer_role:='finops_api';NEW.created_at:=clock_timestamp();
 binding:=public.fleet_native_selection_current(NEW.tenant_id,NEW.old_proposal_id,NEW.candidate_proposal_id);
 SELECT * INTO profile FROM public.workload_safety_profiles WHERE tenant_id=NEW.tenant_id AND workload_id=NEW.workload_id ORDER BY version DESC LIMIT 1;
 SELECT * INTO o FROM public.fleet_configuration_proposals WHERE tenant_id=NEW.tenant_id AND id=NEW.old_proposal_id;
 SELECT * INTO c FROM public.fleet_configuration_proposals WHERE tenant_id=NEW.tenant_id AND id=NEW.candidate_proposal_id;
 IF binding IS NULL OR profile.id IS NULL OR NEW.workload_id IS DISTINCT FROM binding->'old'->'target'->>'workload_id' OR NEW.safety_profile_id IS DISTINCT FROM profile.id OR NEW.safety_profile_version IS DISTINCT FROM profile.version OR coalesce(NEW.creator_id,'')='' OR NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR NEW.document->>'workload_id' IS DISTINCT FROM NEW.workload_id OR NEW.document->>'creator_id' IS DISTINCT FROM NEW.creator_id OR NEW.document->'selection'->'groups'->'binding' IS DISTINCT FROM binding OR NEW.document->'selection'->'groups'->'old_configuration_proposal' IS DISTINCT FROM jsonb_build_object('id',o.id,'sha256',o.content_hash) OR NEW.document->'selection'->'groups'->'candidate_configuration_proposal' IS DISTINCT FROM jsonb_build_object('id',c.id,'sha256',c.content_hash) OR NEW.document->'selection'->'safety_profile' IS DISTINCT FROM jsonb_build_object('id',profile.id,'version',profile.version,'sha256',profile.content_hash) OR NEW.document->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR encode(sha256(NEW.raw_document),'hex') IS DISTINCT FROM NEW.content_hash OR convert_from(NEW.raw_document,'UTF8')::jsonb IS DISTINCT FROM NEW.document OR NOT NEW.document ?& ARRAY['schema_version','id','workload_id','creator_id','selection','execution_authorized','verified_saving'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','id','workload_id','creator_id','selection','execution_authorized','verified_saving'])) THEN RAISE EXCEPTION 'group assessment current selection/profile differs';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER fleet_native_assessment_request_guard BEFORE INSERT ON fleet_native_assessment_requests FOR EACH ROW EXECUTE FUNCTION guard_fleet_native_assessment_request();

-- Exactly the native receipt set selected by the private resolver. Raw XML is
-- still decoded/read back by the dedicated worker; these are database pins,
-- not an assertion that SQL authenticated the provider transport.
CREATE FUNCTION fleet_native_current_pin_ids(p_tenant text,p_binding jsonb) RETURNS text[] LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result text[];sources text[];workload text;BEGIN
 IF p_tenant IS NULL OR p_tenant='' OR p_tenant IS DISTINCT FROM current_setting('app.tenant_id',true) THEN RAISE EXCEPTION 'native pin tenant differs';END IF;
 SELECT array_agg(DISTINCT value->>'source_id') INTO sources FROM jsonb_each(p_binding);
 workload:=p_binding->'old'->'target'->>'workload_id';
 SELECT coalesce(array_agg(x.id ORDER BY x.id),ARRAY[]::text[]) INTO result FROM(
  SELECT m.id FROM jsonb_each(p_binding) side CROSS JOIN LATERAL(
   SELECT r.id FROM public.source_receipts r WHERE r.tenant_id=p_tenant AND r.source_id=side.value->>'source_id' AND r.kind='AWS_FLEET_MEMBERSHIP' AND r.document->>'history_registration_id'=side.value->'registration'->>'id' ORDER BY (r.document->>'collected_at')::timestamptz DESC NULLS LAST,r.created_at DESC,r.id DESC LIMIT 1
  )m
  UNION ALL
  SELECT lt.id FROM unnest(sources) AS selected_source(source_id) CROSS JOIN LATERAL(
   SELECT r.id FROM public.source_receipts r WHERE r.tenant_id=p_tenant AND r.source_id=selected_source.source_id AND r.kind='AWS_FLEET_LAUNCH_TEMPLATES' ORDER BY (r.document->>'collected_at')::timestamptz DESC NULLS LAST,r.created_at DESC,r.id DESC LIMIT 1
  )lt
  UNION ALL
  SELECT h.id FROM(SELECT current.id FROM(SELECT DISTINCT ON(r.document->'binding'->>'provider_resource_id') r.id,r.tenant_id,r.source_id,r.kind,r.document FROM public.source_receipts r WHERE r.tenant_id=p_tenant AND r.source_id=ANY(sources) AND r.kind='AWS_EC2_HARDWARE' AND r.document->'binding'->>'workload_id'=workload ORDER BY r.document->'binding'->>'provider_resource_id',(r.document->>'collected_at')::timestamptz DESC,r.created_at DESC,r.id DESC)current WHERE NOT EXISTS(SELECT 1 FROM public.source_receipts n WHERE n.tenant_id=current.tenant_id AND n.source_id=current.source_id AND n.kind=current.kind AND n.document->'binding'->>'provider_resource_id'=current.document->'binding'->>'provider_resource_id' AND (n.document->>'collected_at')::timestamptz=(current.document->>'collected_at')::timestamptz AND n.document->'raw_object'->>'body_sha256' IS DISTINCT FROM current.document->'raw_object'->>'body_sha256') ORDER BY current.id LIMIT 513)h
 )x;
 IF EXISTS(SELECT 1 FROM public.source_receipts r JOIN public.source_receipts n ON n.tenant_id=r.tenant_id AND n.source_id=r.source_id AND n.kind=r.kind AND (n.document->>'collected_at')::timestamptz=(r.document->>'collected_at')::timestamptz AND (r.kind='AWS_FLEET_LAUNCH_TEMPLATES' OR n.document->>'history_registration_id'=r.document->>'history_registration_id') WHERE r.tenant_id=p_tenant AND r.id=ANY(result) AND r.kind IN('AWS_FLEET_MEMBERSHIP','AWS_FLEET_LAUNCH_TEMPLATES') AND n.document->'raw_object'->>'body_sha256' IS DISTINCT FROM r.document->'raw_object'->>'body_sha256') THEN RAISE EXCEPTION 'group native same-instant capture ambiguous';END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION fleet_native_current_pin_ids(text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fleet_native_current_pin_ids(text,jsonb),fleet_history_json_hash(jsonb),fleet_history_json_text(jsonb) TO finops_group_assessor;

CREATE FUNCTION guard_fleet_native_assessment() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE req public.fleet_native_assessment_requests%ROWTYPE;binding jsonb;profile public.workload_safety_profiles%ROWTYPE;pin jsonb;receipt public.source_receipts%ROWTYPE;rev public.source_revisions%ROWTYPE;member jsonb;result public.native_capacity_results%ROWTYPE;scenario jsonb;k text;old_members jsonb;ids jsonb;covered jsonb;current_pins text[];selected_pins text[];selected_side jsonb;BEGIN
 IF current_user<>'finops_group_assessor' THEN RAISE EXCEPTION 'group assessment requires private evidence reader';END IF;
 NEW.writer_role:='finops_group_assessor';NEW.created_at:=clock_timestamp();
 SELECT * INTO req FROM public.fleet_native_assessment_requests WHERE tenant_id=NEW.tenant_id AND id=NEW.request_id;
 binding:=public.fleet_native_selection_current(NEW.tenant_id,req.old_proposal_id,req.candidate_proposal_id);
 SELECT * INTO profile FROM public.workload_safety_profiles WHERE tenant_id=NEW.tenant_id AND workload_id=req.workload_id ORDER BY version DESC LIMIT 1;
 IF req.id IS NULL OR binding IS NULL OR req.document->'selection'->'groups'->'binding' IS DISTINCT FROM binding OR profile.id IS DISTINCT FROM req.safety_profile_id OR profile.version IS DISTINCT FROM req.safety_profile_version OR NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR NEW.document->'selection' IS DISTINCT FROM req.document->'selection' OR NEW.document->>'status' IS DISTINCT FROM 'BLOCKED' OR NEW.document->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'change_plan_id' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'native_rates'->'selection' IS DISTINCT FROM req.document->'selection'->'groups' OR NEW.document->'native_rates'->>'snapshot_sha256' IS DISTINCT FROM NEW.input_snapshot_hash OR NEW.document->'native_rates'->>'kind' IS DISTINCT FROM 'AWS_GROUP_HISTORICAL_ACCOUNT_RATES' OR NEW.document->'native_rates'->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'native_rates'->'hard_spend_cap' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'native_rates'->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR jsonb_typeof(NEW.document->'observed_at') IS DISTINCT FROM 'string' OR jsonb_typeof(NEW.document->'native_rates'->'observed_at') IS DISTINCT FROM 'string' OR jsonb_typeof(NEW.document->'native_rates'->'valid_until') IS DISTINCT FROM 'string' OR (NEW.document->>'observed_at')::timestamptz<clock_timestamp()-interval '2 minutes' OR (NEW.document->>'observed_at')::timestamptz>clock_timestamp()+interval '5 seconds' OR encode(sha256(NEW.raw_document),'hex') IS DISTINCT FROM NEW.content_hash OR convert_from(NEW.raw_document,'UTF8')::jsonb IS DISTINCT FROM NEW.document THEN RAISE EXCEPTION 'group assessment selected evidence differs';END IF;
 IF NOT NEW.document ?& ARRAY['schema_version','id','selection','observed_at','native_rates','capacity','scenario','status','reason_codes','execution_authorized','change_plan_id','verified_saving'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) x WHERE x<>ALL(ARRAY['schema_version','id','selection','observed_at','native_rates','capacity','scenario','status','reason_codes','execution_authorized','change_plan_id','verified_saving'])) OR jsonb_typeof(NEW.document->'native_rates'->'source_pins') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'native_rates'->'source_pins')>516 OR jsonb_typeof(NEW.document->'native_rates'->'billing_source_refs') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'native_rates'->'billing_source_refs')>24 OR NEW.document->'capacity'->'group_capacity_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'capacity'->'completed_business_work_preserved' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'capacity'->>'historical_membership' IS DISTINCT FROM 'INTERVAL_OWNERSHIP_UNPROVEN' OR jsonb_typeof(NEW.document->'capacity'->'members') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'capacity'->'members')>256 OR jsonb_typeof(NEW.document->'reason_codes') IS DISTINCT FROM 'array' OR NOT(NEW.document->'reason_codes' @> '["EXECUTION_AUTHORITY_NOT_GRANTED","GROUP_CAPACITY_AUTHORITY_UNAVAILABLE"]') OR jsonb_path_exists(NEW.document,'$.**.records') OR jsonb_path_exists(NEW.document,'$.**.points') OR jsonb_path_exists(NEW.document,'$.**.samples') THEN RAISE EXCEPTION 'group assessment bounded observational shape differs';END IF;
 FOR pin IN SELECT value FROM jsonb_array_elements(NEW.document->'native_rates'->'source_pins') LOOP
  SELECT * INTO receipt FROM public.source_receipts WHERE tenant_id=NEW.tenant_id AND id=pin->>'receipt_id';SELECT * INTO rev FROM public.source_revisions WHERE tenant_id=NEW.tenant_id AND id=pin->>'revision_id';
  IF receipt.id IS NULL OR rev.id IS NULL OR receipt.revision_id IS DISTINCT FROM rev.id OR receipt.writer_role<>'finops_ingester' OR rev.writer_role<>'finops_ingester' OR receipt.source_id IS DISTINCT FROM rev.source_id OR receipt.document->'raw_object'->>'body_sha256' IS DISTINCT FROM pin->>'raw_sha256' OR rev.document->'raw_object'->>'body_sha256' IS DISTINCT FROM pin->>'raw_sha256' OR receipt.document->'raw_object'->>'version_id' IS DISTINCT FROM pin->>'receipt_version_id' OR rev.document->'raw_object'->>'version_id' IS DISTINCT FROM pin->>'revision_version_id' OR public.fleet_history_json_hash(receipt.document||jsonb_build_object('writer_role',receipt.writer_role,'created_at',receipt.created_at)) IS DISTINCT FROM pin->>'receipt_sha256' THEN RAISE EXCEPTION 'group assessment native pin differs';END IF;
  IF receipt.source_id NOT IN(binding->'old'->>'source_id',binding->'candidate'->>'source_id') OR NOT EXISTS(SELECT 1 FROM jsonb_each(binding) x WHERE x.value->>'source_id'=receipt.source_id AND x.value->>'source_config_sha256'=receipt.document->>'config_hash' AND x.value->'source_registration_version'=receipt.document->'registration_version') OR receipt.document->>'config_hash' IS DISTINCT FROM rev.document->>'config_hash' OR receipt.document->'registration_version' IS DISTINCT FROM rev.document->'registration_version' THEN RAISE EXCEPTION 'group assessment pin source revision differs';END IF;
  IF receipt.kind NOT IN('AWS_FLEET_MEMBERSHIP','AWS_FLEET_LAUNCH_TEMPLATES','AWS_EC2_HARDWARE') THEN RAISE EXCEPTION 'group assessment native pin kind differs';END IF;
  IF receipt.kind='AWS_FLEET_MEMBERSHIP' THEN
   SELECT value INTO selected_side FROM jsonb_each(binding) WHERE value->'registration'->>'id'=receipt.document->>'history_registration_id';
   IF selected_side IS NULL OR receipt.document->'history_registration_version' IS DISTINCT FROM selected_side->'registration'->'version' OR receipt.document->>'history_registration_hash' IS DISTINCT FROM selected_side->'registration'->>'sha256' OR receipt.document->'binding' IS DISTINCT FROM jsonb_build_object('tenant_id',NEW.tenant_id,'workload_id',req.workload_id,'provider','AWS','account_id',selected_side->'target'->>'account_id','region',selected_side->'target'->>'region') OR jsonb_array_length(receipt.document->'groups')<>1 OR receipt.document->'groups'->0->>'arn' IS DISTINCT FROM selected_side->'target'->>'asg_arn' THEN RAISE EXCEPTION 'group assessment membership selector differs';END IF;
  END IF;
  IF receipt.kind='AWS_FLEET_MEMBERSHIP' AND receipt.document->>'history_registration_id'=binding->'old'->'registration'->>'id' THEN
   IF old_members IS NOT NULL OR jsonb_array_length(receipt.document->'groups')<>1 OR receipt.document->'groups'->0->>'arn' IS DISTINCT FROM binding->'old'->'target'->>'asg_arn' THEN RAISE EXCEPTION 'group assessment old membership ambiguous';END IF;
   SELECT coalesce(jsonb_agg(value->>'instance_id' ORDER BY value->>'instance_id'),'[]') INTO old_members FROM jsonb_array_elements(receipt.document->'groups'->0->'members');
  END IF;
  IF NEW.document->'native_rates'->>'status'='OBSERVED_CONDITIONAL' AND (jsonb_typeof(receipt.document->'collected_at') IS DISTINCT FROM 'string' OR (receipt.document->>'collected_at')::timestamptz<clock_timestamp()-interval '5 minutes' OR (receipt.document->>'collected_at')::timestamptz>clock_timestamp()+interval '5 seconds') THEN RAISE EXCEPTION 'conditional group native pin expired';END IF;
 END LOOP;
 FOR pin IN SELECT value FROM jsonb_array_elements(NEW.document->'native_rates'->'billing_source_refs') LOOP
  SELECT * INTO receipt FROM public.source_receipts WHERE tenant_id=NEW.tenant_id AND id=pin->>'receipt_id';
  IF jsonb_typeof(receipt.document->'source_proof'->'billing_period_start') IS DISTINCT FROM 'string' OR (receipt.document->'source_proof'->>'billing_period_start')::timestamptz IS DISTINCT FROM (date_trunc('month',(receipt.document->'source_proof'->>'billing_period_start')::timestamptz AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') THEN RAISE EXCEPTION 'group assessment billing month invalid';END IF;
  IF receipt.id IS NULL OR receipt.kind<>'AWS_CUR2' OR receipt.writer_role<>'finops_ingester' OR receipt.source_id IS DISTINCT FROM binding->'old'->>'source_id' OR receipt.document->>'config_hash' IS DISTINCT FROM binding->'old'->>'source_config_sha256' OR receipt.revision_id IS DISTINCT FROM pin->>'revision_id' OR receipt.document->>'ingestion_job_id' IS DISTINCT FROM pin->>'ingestion_job_id' OR receipt.document->>'raw_hash' IS DISTINCT FROM pin->>'raw_hash' OR receipt.document->>'canonical_hash' IS DISTINCT FROM pin->>'canonical_hash' OR NOT EXISTS(SELECT 1 FROM public.source_checkpoints c WHERE c.tenant_id=NEW.tenant_id AND c.source_id=receipt.source_id AND c.checkpoint_key='month:'||(binding->'old'->>'source_config_sha256')||':'||to_char((receipt.document->'source_proof'->>'billing_period_start')::timestamptz AT TIME ZONE 'UTC','YYYY-MM') AND c.document->>'receipt_id'=receipt.id) THEN RAISE EXCEPTION 'group assessment billing current head differs';END IF;
 END LOOP;
 IF jsonb_typeof(NEW.document->'native_rates'->'current_member_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'native_rates'->'current_member_ids')>256 OR jsonb_typeof(NEW.document->'capacity'->'missing_instance_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'group assessment population shape differs';END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY value),'[]') INTO ids FROM jsonb_array_elements_text(NEW.document->'native_rates'->'current_member_ids');
 SELECT coalesce(jsonb_agg(x.id ORDER BY x.id),'[]') INTO covered FROM(SELECT value->>'instance_id' id FROM jsonb_array_elements(NEW.document->'capacity'->'members') UNION ALL SELECT value FROM jsonb_array_elements_text(NEW.document->'capacity'->'missing_instance_ids'))x;
 IF ids IS DISTINCT FROM covered OR (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(ids))<>jsonb_array_length(ids) OR (jsonb_array_length(NEW.document->'capacity'->'members')=0 AND NEW.document->'capacity'->>'status' IS DISTINCT FROM 'UNAVAILABLE') OR (jsonb_array_length(NEW.document->'capacity'->'members')>0 AND jsonb_array_length(NEW.document->'capacity'->'missing_instance_ids')>0 AND NEW.document->'capacity'->>'status' IS DISTINCT FROM 'PARTIAL') OR (jsonb_array_length(NEW.document->'capacity'->'members')>0 AND jsonb_array_length(NEW.document->'capacity'->'missing_instance_ids')=0 AND NEW.document->'capacity'->>'status' IS DISTINCT FROM 'CURRENT_MEMBER_RESULTS_OBSERVED') THEN RAISE EXCEPTION 'group assessment member coverage differs';END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(NEW.document->'capacity'->'members') LOOP
  SELECT * INTO result FROM public.native_capacity_results WHERE tenant_id=NEW.tenant_id AND id=member->>'result_id';
  IF result.id IS NULL OR result.workload_id IS DISTINCT FROM req.workload_id OR result.resource_id IS DISTINCT FROM member->>'resource_id' OR result.content_hash IS DISTINCT FROM member->>'result_sha256' OR result.hardware_receipt_id IS DISTINCT FROM member->>'hardware_receipt_id' OR result.safety_profile_id IS DISTINCT FROM profile.id OR result.document->'binding'->>'provider_resource_id' IS DISTINCT FROM member->>'instance_id' OR result.document->>'status' IS DISTINCT FROM member->>'status' OR member->>'status' NOT IN('BLOCKED','INSUFFICIENT_OBSERVATION') OR jsonb_typeof(member->'demand_meaning') IS DISTINCT FROM 'string' OR member->>'demand_meaning' NOT IN('REQUEST_THROUGHPUT_PROXY','LEGACY_UNPROVEN_PROXY','UNAVAILABLE') OR EXISTS(SELECT 1 FROM jsonb_object_keys(member) k WHERE k<>ALL(ARRAY['instance_id','resource_id','result_id','result_sha256','hardware_receipt_id','status','demand_meaning'])) THEN RAISE EXCEPTION 'group assessment individual result pin differs';END IF;
 END LOOP;
 scenario:=NEW.document->'scenario';
 IF scenario->>'basis' IS DISTINCT FROM 'LIKE_FOR_LIKE_CURRENT_MEMBER_COUNT' OR scenario->>'rate_basis' IS DISTINCT FROM 'HISTORICAL_ACCOUNT_RATE_ESTIMATE' OR scenario->'estimated_saving' IS DISTINCT FROM 'null'::jsonb OR scenario->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR scenario->'contracted_avoidable_cost' IS DISTINCT FROM 'null'::jsonb OR scenario->'hard_spend_cap' IS DISTINCT FROM 'false'::jsonb OR NOT scenario ?& ARRAY['status','currency','member_count','old_hourly_rate','candidate_hourly_rate','old_hourly_compute','candidate_hourly_compute','hourly_compute_difference'] THEN RAISE EXCEPTION 'group scenario cannot grant money authority';END IF;
 IF scenario->>'status'='OBSERVED_CONDITIONAL' THEN
  current_pins:=public.fleet_native_current_pin_ids(NEW.tenant_id,binding);
  SELECT coalesce(array_agg(value->>'receipt_id' ORDER BY value->>'receipt_id'),ARRAY[]::text[]) INTO selected_pins FROM jsonb_array_elements(NEW.document->'native_rates'->'source_pins');
  IF current_pins IS DISTINCT FROM selected_pins OR cardinality(current_pins)<5 OR (SELECT count(DISTINCT x) FROM unnest(selected_pins) x)<>cardinality(selected_pins) THEN RAISE EXCEPTION 'conditional group complete current native pin set differs';END IF;
  IF (NEW.document->'native_rates'->>'observed_at')::timestamptz<clock_timestamp()-interval '2 minutes' OR (NEW.document->'native_rates'->>'observed_at')::timestamptz>clock_timestamp()+interval '5 seconds' OR (NEW.document->'native_rates'->>'valid_until')::timestamptz>(NEW.document->'native_rates'->>'observed_at')::timestamptz+interval '24 hours' OR jsonb_typeof(NEW.document->'native_rates'->'baseline'->'start') IS DISTINCT FROM 'string' OR jsonb_typeof(NEW.document->'native_rates'->'baseline'->'end') IS DISTINCT FROM 'string' OR (NEW.document->'native_rates'->'baseline'->>'end')::timestamptz-(NEW.document->'native_rates'->'baseline'->>'start')::timestamptz<>interval '14 days' OR ((NEW.document->'native_rates'->'baseline'->>'end')::timestamptz AT TIME ZONE 'UTC')::time<>time '00:00:00' OR (NEW.document->'native_rates'->'baseline'->>'end')::timestamptz>(NEW.document->'native_rates'->>'observed_at')::timestamptz OR (NEW.document->'native_rates'->>'valid_until')::timestamptz>(NEW.document->'native_rates'->'baseline'->>'end')::timestamptz+interval '48 hours' THEN RAISE EXCEPTION 'conditional group observation or billing horizon differs';END IF;
  IF old_members IS NULL OR ids IS DISTINCT FROM old_members OR jsonb_array_length(ids)<>coalesce((scenario->>'member_count')::int,0) OR jsonb_array_length(NEW.document->'native_rates'->'billing_source_refs')=0 THEN RAISE EXCEPTION 'conditional group scenario native population required';END IF;
  IF NEW.document->'native_rates'->>'status' IS DISTINCT FROM 'OBSERVED_CONDITIONAL' OR (NEW.document->'native_rates'->>'valid_until')::timestamptz<=clock_timestamp() OR coalesce(scenario->>'currency','')!~'^[A-Z]{3}$' OR jsonb_typeof(scenario->'member_count') IS DISTINCT FROM 'number' OR coalesce(scenario->>'member_count','')!~'^[1-9][0-9]{0,2}$' OR (scenario->>'member_count')::int<1 OR (scenario->>'member_count')::int>256 THEN RAISE EXCEPTION 'conditional group scenario scope invalid';END IF;
  FOREACH k IN ARRAY ARRAY['old_hourly_rate','candidate_hourly_rate','old_hourly_compute','candidate_hourly_compute','hourly_compute_difference'] LOOP IF jsonb_typeof(scenario->k) IS DISTINCT FROM 'string' OR coalesce(scenario->>k,'')!~'^-?(0|[1-9][0-9]{0,25})(\.[0-9]{1,12})?$' THEN RAISE EXCEPTION 'conditional group decimal invalid';END IF;END LOOP;
  IF (scenario->>'old_hourly_rate')::numeric<=0 OR (scenario->>'candidate_hourly_rate')::numeric<=0 OR (scenario->>'old_hourly_compute')::numeric<>(scenario->>'old_hourly_rate')::numeric*(scenario->>'member_count')::int OR (scenario->>'candidate_hourly_compute')::numeric<>(scenario->>'candidate_hourly_rate')::numeric*(scenario->>'member_count')::int OR (scenario->>'hourly_compute_difference')::numeric<>(scenario->>'old_hourly_compute')::numeric-(scenario->>'candidate_hourly_compute')::numeric OR scenario->>'old_hourly_rate' IS DISTINCT FROM NEW.document->'native_rates'->'old'->>'observed_hourly_rate' OR scenario->>'candidate_hourly_rate' IS DISTINCT FROM NEW.document->'native_rates'->'candidate'->>'observed_hourly_rate' OR scenario->>'currency' IS DISTINCT FROM NEW.document->'native_rates'->'old'->'rate_dimensions'->>'currency' OR scenario->>'currency' IS DISTINCT FROM NEW.document->'native_rates'->'candidate'->'rate_dimensions'->>'currency' THEN RAISE EXCEPTION 'conditional group arithmetic or currency differs';END IF;
 ELSIF scenario->>'status'='UNAVAILABLE' THEN
  IF NEW.document->'native_rates'->>'status' IS DISTINCT FROM 'UNAVAILABLE' OR jsonb_typeof(scenario->'member_count') IS DISTINCT FROM 'number' OR scenario->>'member_count' IS DISTINCT FROM '0' THEN RAISE EXCEPTION 'unavailable group classification differs';END IF;
  FOREACH k IN ARRAY ARRAY['observed_hourly_rate','usage_hours','observed_current_member_compute_cost','rate_dimensions'] LOOP IF coalesce(NEW.document->'native_rates'->'old'->k,'null') IS DISTINCT FROM 'null'::jsonb OR coalesce(NEW.document->'native_rates'->'candidate'->k,'null') IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'unavailable native rates invented money';END IF;END LOOP;
  FOREACH k IN ARRAY ARRAY['currency','old_hourly_rate','candidate_hourly_rate','old_hourly_compute','candidate_hourly_compute','hourly_compute_difference'] LOOP IF scenario->k IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'unavailable group scenario invented money';END IF;END LOOP;
 ELSE RAISE EXCEPTION 'group scenario status invalid';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER fleet_native_assessment_guard BEFORE INSERT ON fleet_native_assessments FOR EACH ROW EXECUTE FUNCTION guard_fleet_native_assessment();
